renderStage(){this.renderer.render(this.doc,this.time,this.playing?null:this.onion);$('#playback-frame').textContent='Frame '+Math.floor(this.time*this.doc.fps)+' / '+Math.ceil(this.doc.duration*this.doc.fps);this.stage?.handles();$('#clock').textContent=`${String(Math.floor(this.time/60)).padStart(2,'0')}:${(this.time%60).toFixed(2).padStart(5,'0')}`;this.timeline?.playhead();const range=loopRange(this.doc);$('#loop-summary').textContent=formatTime(this.doc,range.start,this.timeline?.measurement)+' – '+formatTime(this.doc,range.end,this.timeline?.measurement);}
render(){this.selected=this.selected.filter(id=>find(this.doc,id));this.renderStage();this.properties.render();renderContext(this);this.timeline.render();$('#project-name').textContent=this.doc.name;$('#composition-meta').textContent=`${this.doc.width} × ${this.doc.height} · ${this.doc.fps} fps`;$('#selection-info').textContent=this.selected.length===1?find(this.doc,this.selected[0])?.name:this.selected.length?`${this.selected.length} objects selected`:'Nothing selected';$('#theme').textContent=document.documentElement.dataset.theme==='dark'?'☀':'☾';$('#theme').setAttribute('aria-label',document.documentElement.dataset.theme==='dark'?'Switch to light mode':'Switch to dark mode');$('#multi').classList.toggle('active',this.multi);$('#snap').classList.toggle('active',this.snap);$('#precision').classList.toggle('active',this.precision);$('#tap-select').classList.toggle('active',this.tapSelect);$('#group').disabled=this.selected.length<2;$('#ungroup').disabled=find(this.doc,this.selected[0])?.type!=='group';$('#undo').disabled=!this.history.undoStack.length;$('#redo').disabled=!this.history.redoStack.length;$('#audio-status').textContent=this.doc.audio?`${this.doc.audio.name} · ${(this.doc.audio.trimEnd-this.doc.audio.trimStart).toFixed(1)}s`:'No audio yet';for(const b of document.querySelectorAll('[data-tool]')){const active=b.dataset.tool===this.tool||(b.dataset.tool==='shapes'&&shapeTools.includes(this.tool));b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);if(b.dataset.tool==='shapes'){b.title=shapeTools.includes(this.tool)?'Shapes · '+this.tool:'Shapes';const chosen={rect:'Rectangle',ellipse:'Ellipse',triangle:'Triangle',polygon:'Polygon',star:'Star',line:'Line'}[this.tool];b.querySelector('span').textContent=chosen||'Shapes';b.setAttribute('aria-label',chosen?'Shapes · '+chosen:'Shapes');b.removeAttribute('aria-haspopup');b.setAttribute('aria-expanded',!!this.shapesOpen);}};for(const [id,state] of [['multi',this.multi],['snap',this.snap],['tap-select',this.tapSelect],['precision',this.precision],['loop',this.loop]])$('#'+id).setAttribute('aria-pressed',state);$('#stage-hint').innerHTML=this.tool==='path'?'<button id="finish-path">Finish path ✓</button> Tap nodes · drag to curve':this.tool==='mesh'?'Hold a mesh point for colour · two-finger tap to undo':this.tool==='direct'?'Tap a shape or point to edit · drag an empty area to select':this.tool==='select'?'Tap to select · drag to move · two-finger tap to undo':'Drag to draw · double-tap empty canvas to add';$('#finish-path')?.addEventListener('pointerdown',e=>{e.stopPropagation();this.stage.finishPath();});$('#stage-hint').style.pointerEvents=this.tool==='path'?'auto':'none';}
rememberColor(color){if(!/^#[0-9a-f]{6}$/i.test(color))return;this.drawColor=color;try{localStorage.setItem('poppy-draw-color',color);}catch{}}
